//! Synthetic source bytes for comparing a projection's derived records with
//! its gather and pack: deterministic, finite values generated by offset,
//! so no checkpoint payload is read.
//!
//! Test support source, outside model-compiler-sdk's module tree: a model's
//! tests include it by `#[path]` and supply its dependencies, so no build
//! of the SDK, a host, a bundle or a package reads it. Each including test
//! uses part of it.
#![allow(dead_code)]

use kernel_core::contract::DType;
use kernel_core::precision::TensorSpan;
use kernel_core::precision::packed::PackedMatrix;
use kernel_core::weight_transform::PackedSection;
use projection_spec::derive::{DerivedOperation, OperandSlice};

use model_compiler_sdk::quantization::packing::{PackedWeightBuilder, PackedWeights};

/// Deterministic source bytes of `span` from byte `offset`, seeded by its
/// tensor name: finite F32 and BF16 values, other dtypes below 112.
pub fn fill_source(span: &TensorSpan, offset: u64, out: &mut [u8]) {
    let seed = span
        .tensor
        .bytes()
        .fold(0u64, |s, b| s.wrapping_mul(33).wrapping_add(u64::from(b)));
    for (index, byte) in out.iter_mut().enumerate() {
        let n = offset + index as u64;
        *byte = match span.dtype {
            DType::F32 => (0.5_f32
                + (((n / 4).wrapping_mul(37) ^ ((n / 4) >> 9) ^ seed) % 4093) as f32 / 256.0)
                .to_le_bytes()[n as usize % 4],
            DType::Bf16 => (0x3e00_u16
                + (((n / 2).wrapping_mul(37) ^ ((n / 2) >> 9) ^ seed) % 511) as u16)
                .to_le_bytes()[n as usize % 2],
            _ => ((n.wrapping_mul(37) ^ (n >> 9) ^ seed) % 112) as u8,
        };
    }
}

/// All of `span`'s [`fill_source`] bytes.
pub fn synthetic_source(span: &TensorSpan) -> Vec<u8> {
    let mut bytes = vec![0; span.byte_length as usize];
    fill_source(span, 0, &mut bytes);
    bytes
}

/// The operand `slice` of a synthetic source, gathered: only `section`'s
/// bytes are generated, the rest of the source is zero, and global scales
/// are always generated.
pub fn selected_source_payload(slice: &OperandSlice, section: PackedSection) -> PackedMatrix {
    selected_source_payload_with(slice, section, synthetic_source)
}

/// Gather a section with a source generator that satisfies the consumer's
/// numerical domain as well as the stored dtype.
pub fn selected_source_payload_with(
    slice: &OperandSlice,
    section: PackedSection,
    source: impl Fn(&TensorSpan) -> Vec<u8>,
) -> PackedMatrix {
    use kernel_core::precision::packed::{MatrixView, ScaleBytes};
    let weight = &slice.source.weight;
    // Only the compared section needs position-dependent values. The other
    // buffers satisfy the repacker's shape contract without extra generation.
    let codes = if section == PackedSection::Codes {
        source(&weight.codes)
    } else {
        vec![0; weight.codes.byte_length as usize]
    };
    let local = weight.local_scale.as_ref().map(|s| {
        if section == PackedSection::LocalScales {
            source(&s.tensor)
        } else {
            vec![0; s.tensor.byte_length as usize]
        }
    });
    let global = weight.global_scale.as_ref().map(|s| source(&s.tensor));
    let view = MatrixView {
        tensor: &weight.codes.tensor,
        format: weight.format,
        rows: weight.logical_shape[weight.logical_shape.len() - 2] as usize,
        k: *weight.logical_shape.last().unwrap() as usize,
        row_origin: 0,
        k_origin: 0,
        nibble_order: kernel_core::precision::NibbleOrder::EvenLow,
        codes: &codes,
        local: weight.local_scale.as_ref().map(|s| ScaleBytes {
            dtype: if s.tensor.dtype == DType::U8 {
                DType::Ue8M0
            } else {
                s.tensor.dtype
            },
            bytes: local.as_ref().unwrap(),
        }),
        global: weight.global_scale.as_ref().map(|s| ScaleBytes {
            dtype: s.tensor.dtype,
            bytes: global.as_ref().unwrap(),
        }),
    };
    projection_spec::derive::payload::slice(slice, view).unwrap()
}

/// An operation's synthetic payloads and their packing.
pub struct SyntheticPayload {
    /// Each source span's bytes: the codes, then the local and global
    /// scales the weight has.
    pub payloads: Vec<Vec<u8>>,
    /// The operation's first slice gathered from `payloads` and packed by
    /// its packing plan.
    pub packed: PackedWeights,
}

/// The synthetic payloads of `operation`'s first slice (codes in a ramp of
/// small values, scales from a short cycle), gathered by its selection and
/// packed by its plan.
pub fn synthetic_payload(operation: &DerivedOperation) -> SyntheticPayload {
    use kernel_core::precision::packed::{MatrixSlice, MatrixView, ScaleBytes};
    let slice = &operation.slices[0];
    let weight = &slice.source.weight;
    let spans: Vec<_> = std::iter::once(&weight.codes)
        .chain(weight.local_scale.iter().map(|s| &s.tensor))
        .chain(weight.global_scale.iter().map(|s| &s.tensor))
        .collect();
    let payloads: Vec<Vec<u8>> = spans
        .iter()
        .enumerate()
        .map(|(index, span)| {
            if index == 0 && span.dtype == DType::Bf16 {
                (0..span.byte_length / 2)
                    .flat_map(|n| (0x3e00_u16 + ((n * 37 + (n >> 9)) % 512) as u16).to_le_bytes())
                    .collect()
            } else if index == 0 {
                (0..span.byte_length)
                    .map(|n| ((n * 37 + (n >> 9)) % 127) as u8)
                    .collect()
            } else {
                match span.dtype {
                    DType::F32 => (0..span.byte_length / 4)
                        .flat_map(|n| (0.25_f32 + (n % 16) as f32).to_le_bytes())
                        .collect(),
                    DType::Bf16 => (0..span.byte_length / 2)
                        .flat_map(|n| (0x3e80_u16 + (n % 16) as u16).to_le_bytes())
                        .collect(),
                    _ => vec![127; span.byte_length as usize],
                }
            }
        })
        .collect();
    let local_dtype = weight.local_scale.as_ref().map(|s| {
        if s.tensor.dtype == DType::U8 {
            DType::Ue8M0
        } else {
            s.tensor.dtype
        }
    });
    let source = MatrixView {
        tensor: &weight.codes.tensor,
        format: weight.format,
        rows: weight.logical_shape[0] as usize,
        k: weight.logical_shape[1] as usize,
        row_origin: 0,
        k_origin: 0,
        nibble_order: kernel_core::precision::NibbleOrder::EvenLow,
        codes: &payloads[0],
        local: local_dtype.map(|dtype| ScaleBytes {
            dtype,
            bytes: &payloads[1],
        }),
        global: weight.global_scale.as_ref().map(|_| ScaleBytes {
            dtype: DType::F32,
            bytes: payloads.last().unwrap(),
        }),
    };
    let gathered = projection_spec::derive::payload::slice(slice, source).unwrap();
    let mut builder = PackedWeightBuilder::new(operation.packing.clone()).unwrap();
    builder
        .write_matrix(
            0,
            0,
            gathered.view("selected"),
            &MatrixSlice {
                rows: (0..gathered.rows).collect(),
                k_start: 0,
                k: gathered.k,
                padded_rows: gathered.rows,
                padded_k: gathered.k,
                nibble_order: gathered.nibble_order,
            },
        )
        .unwrap();
    let actual = builder.finish().unwrap();
    SyntheticPayload {
        payloads,
        packed: actual,
    }
}
